def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    lattice = max(counts, key=counts.get)
    fill = max((v for v in counts if v != lattice), key=counts.get)

    def marker_lines(horizontal):
        n = h if horizontal else w
        m = w if horizontal else h
        scores = []
        for i in range(n):
            line = [grid[i][j] if horizontal else grid[j][i] for j in range(m)]
            scores.append(sum(v == lattice for v in line))
        return scores

    def find_period(scores):
        best = None
        for p in range(2, 9):
            for phase in range(p):
                score = sum(scores[i] for i in range(phase, len(scores), p))
                if best is None or score > best[0]:
                    best = (score, p, phase)
        return best[1], best[2]

    rp, rphase = find_period(marker_lines(True))
    cp, cphase = find_period(marker_lines(False))
    rows = list(range(rphase, h, rp))
    cols = list(range(cphase, w, cp))

    return [[fill if grid[r][c] == lattice else grid[r][c] for c in cols]
            for r in rows]
